import { relations } from "drizzle-orm";
import {
  bigint,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uuid,
} from "drizzle-orm/pg-core";
import type { GameEvent, RuntimeState } from "@iz/schema";

/**
 * Database schema (master prompt §15). uuid primary keys generated by
 * Postgres, timestamptz everywhere. No raw SQL outside migrations: everything
 * goes through the Drizzle query builder.
 */

export const users = pgTable(
  "users",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    /** "guest" | "github" */
    kind: text("kind").notNull(),
    githubId: text("github_id"),
    displayName: text("display_name").notNull(),
    recoveryCodeHash: text("recovery_code_hash"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("users_recovery_code_hash_uq").on(t.recoveryCodeHash),
    unique("users_github_id_uq").on(t.githubId),
  ]
);

export const teams = pgTable("teams", {
  id: uuid("id").primaryKey().defaultRandom(),
  worldId: text("world_id").notNull(),
  worldVersion: text("world_version").notNull(),
  bundleHash: text("bundle_hash").notNull(),
  name: text("name").notNull(),
  inviteCodeHash: text("invite_code_hash"),
  /** "session" | "global" — from the world's clock def (§13). */
  clockMode: text("clock_mode").notNull(),
  startedAt: timestamp("started_at", { withTimezone: true }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export const teamMembers = pgTable(
  "team_members",
  {
    teamId: uuid("team_id")
      .notNull()
      .references(() => teams.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    /** "owner" | "member" */
    role: text("role").notNull(),
    joinedAt: timestamp("joined_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ name: "team_members_pk", columns: [t.teamId, t.userId] }),
    index("team_members_user_idx").on(t.userId),
  ]
);

export const events = pgTable(
  "events",
  {
    id: bigint("id", { mode: "number" }).generatedAlwaysAsIdentity({ name: "events_id_seq" }).primaryKey(),
    teamId: uuid("team_id")
      .notNull()
      .references(() => teams.id, { onDelete: "cascade" }),
    seq: integer("seq").notNull(),
    type: text("type").notNull(),
    /** The full GameEvent (§9), including "type" — the log is the source of truth. */
    payload: jsonb("payload").$type<GameEvent>().notNull(),
    actorUserId: uuid("actor_user_id"),
    /** "human" | "agent" */
    actorKind: text("actor_kind").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("events_team_seq_uq").on(t.teamId, t.seq),
    index("events_type_idx").on(t.type),
  ]
);

/** Cache only (§15): every 200 events. Never authoritative. */
export const snapshots = pgTable(
  "snapshots",
  {
    teamId: uuid("team_id")
      .notNull()
      .references(() => teams.id, { onDelete: "cascade" }),
    seq: integer("seq").notNull(),
    state: jsonb("state").$type<RuntimeState>().notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ name: "snapshots_pk", columns: [t.teamId, t.seq] })]
);

/** Private per user, never broadcast (§12). */
export const privateNotes = pgTable(
  "private_notes",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    teamId: uuid("team_id")
      .notNull()
      .references(() => teams.id, { onDelete: "cascade" }),
    body: text("body").notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("private_notes_user_team_idx").on(t.userId, t.teamId)]
);

export const privateClaims = pgTable(
  "private_claims",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    teamId: uuid("team_id")
      .notNull()
      .references(() => teams.id, { onDelete: "cascade" }),
    text: text("text").notNull(),
    slots: jsonb("slots").$type<Record<string, string>>(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("private_claims_user_team_idx").on(t.userId, t.teamId)]
);

export const agentTokens = pgTable(
  "agent_tokens",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    teamId: uuid("team_id")
      .notNull()
      .references(() => teams.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    tokenHash: text("token_hash").notNull(),
    label: text("label").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    lastUsedAt: timestamp("last_used_at", { withTimezone: true }),
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
  },
  (t) => [unique("agent_tokens_token_hash_uq").on(t.tokenHash), index("agent_tokens_team_idx").on(t.teamId)]
);

export const benchmarkRuns = pgTable("benchmark_runs", {
  id: uuid("id").primaryKey().defaultRandom(),
  teamId: uuid("team_id")
    .notNull()
    .references(() => teams.id, { onDelete: "cascade" }),
  worldId: text("world_id").notNull(),
  agentLabel: text("agent_label").notNull(),
  startedAt: timestamp("started_at", { withTimezone: true }).notNull(),
  finishedAt: timestamp("finished_at", { withTimezone: true }),
  metrics: jsonb("metrics").$type<Record<string, unknown>>(),
});

export const sessionsWeb = pgTable(
  "sessions_web",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    tokenHash: text("token_hash").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  },
  (t) => [unique("sessions_web_token_hash_uq").on(t.tokenHash), index("sessions_web_user_idx").on(t.userId)]
);

export const usersRelations = relations(users, ({ many }) => ({
  memberships: many(teamMembers),
  sessions: many(sessionsWeb),
}));

export const teamsRelations = relations(teams, ({ many }) => ({
  members: many(teamMembers),
  events: many(events),
}));

export const teamMembersRelations = relations(teamMembers, ({ one }) => ({
  team: one(teams, { fields: [teamMembers.teamId], references: [teams.id] }),
  user: one(users, { fields: [teamMembers.userId], references: [users.id] }),
}));

export type UserRow = typeof users.$inferSelect;
export type TeamRow = typeof teams.$inferSelect;
export type TeamMemberRow = typeof teamMembers.$inferSelect;
export type EventRow = typeof events.$inferSelect;
export type SessionWebRow = typeof sessionsWeb.$inferSelect;
export type PrivateNotesRow = typeof privateNotes.$inferSelect;
export type PrivateClaimsRow = typeof privateClaims.$inferSelect;
export type AgentTokenRow = typeof agentTokens.$inferSelect;
export type BenchmarkRunRow = typeof benchmarkRuns.$inferSelect;
